let currentLang = DEFAULT_LANG;

const langListeners = new Set();

function notifyLang() {
  langListeners.forEach((fn) => fn(currentLang));
}

export function subscribeLanguage(fn) {
  langListeners.add(fn);
  return () => langListeners.delete(fn);
}

export function getSupportedLanguages() {
  return SUPPORTED_LANGUAGES;
}

export function setLanguage(lang) {
  currentLang = lang in DICTIONARY ? lang : DEFAULT_LANG;
  notifyLang();
  return AsyncStorage.setItem(STORAGE_KEY, currentLang);
}

export async function loadLanguage() {
  try {
    const saved = await AsyncStorage.getItem(STORAGE_KEY);
    currentLang = saved in DICTIONARY ? saved : DEFAULT_LANG;
  } catch (e) {
    currentLang = DEFAULT_LANG;
  }
  notifyLang();
  return currentLang;
}

export function getCurrentLanguage() {
  return currentLang;
}

export function t(key) {
  const lang = DICTIONARY[currentLang] || DICTIONARY[DEFAULT_LANG];
  return (lang && lang[key]) || DICTIONARY[DEFAULT_LANG][key] || key;
}

// Translate a real-estate asset name by its id (e.g. 're_studio').
export function tRealEstate(id) {
  return t('re_' + id.replace(/^re_/, ''));
}

// Translate a business subtype name. Pass the category key + subType key.
export function tBusinessName(catKey, subKey) {
  const k = `biz_${catKey}_${subKey}`;
  const v = t(k);
  return v === k ? null : v; // null if no translation key exists
}

// Translate a business category name.
export function tBusinessCategory(catKey) {
  const k = `biz_cat_${catKey}`;
  return t(k);
}

// Translate a business sub-category name.
export function tBusinessSubCategory(subCat) {
  const k = `biz_subcat_${String(subCat).toLowerCase().replace(/[^a-z0-9]/g, '')}`;
  return t(k);
}

// Translate a job title/description by id.
export function tJobTitle(id) {
  return t('job_' + id);
}
export function tJobDesc(id) {
  return t('job_' + id + '_desc');
}

// Formatted translation: replaces {placeholder} tokens with values from `vars`.
// e.g. tf('hired_as', { title: 'Chef' }) => "Hired as Chef!"
export function tf(key, vars) {
  let str = t(key);
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
    }
  }
  return str;
}

// React hook (for use with useSyncExternalStore) - import this in components
// that need to re-render when the language changes.
export function subscribeLanguageForStore(fn) {
  return subscribeLanguage(fn);
}

export function getCurrentLanguageForStore() {
  return currentLang;
}
